import sys
from collections import deque

MOD = 1000000007

def count_ways(n, edges):
    graph = [[] for _ in range(2 * n)]
    degree = [0] * (2 * n)

    for u, v in edges:
        u -= 1
        v -= 1
        graph[u].append(v)
        graph[v].append(u)
        degree[u] += 1
        degree[v] += 1

    leaves = deque()
    for i in range(2 * n):
        if degree[i] == 1:
            leaves.append(i)

    while len(leaves) > 2:
        leaf = leaves.popleft()
        for neighbor in graph[leaf]:
            degree[neighbor] -= 1
            if degree[neighbor] == 1:
                leaves.append(neighbor)

    if len(leaves) != 2:
        return 0

    root = leaves[0]
    parent = [-1] * (2 * n)
    stack = [root]
    while stack:
        node = stack.pop()
        for neighbor in graph[node]:
            if parent[neighbor] == -1 and neighbor != root:
                parent[neighbor] = node
                stack.append(neighbor)

    def dfs(node):
        if not graph[node]:
            return 1, 1
        ways = 1
        positions = 0
        for child in graph[node]:
            if child != parent[node]:
                child_ways, child_positions = dfs(child)
                ways = (ways * child_ways) % MOD
                positions += child_positions
        if positions == 0:
            return ways, 1
        else:
            return ways, positions + 1

    total_ways, total_positions = dfs(root)
    if total_positions != n:
        return 0

    return (total_ways * 2) % MOD

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    index += 1
    edges = []
    for _ in range(2 * n - 1):
        u = int(input[index])
        v = int(input[index + 1])
        edges.append((u, v))
        index += 2
    result = count_ways(n, edges)
    print(result)

if __name__ == "__main__":
    main()
